def ladder_length(begin, end, words):
    unused = set(words)
    queue = deque([(begin, 1)])
    while queue:
        word, dist = queue.popleft()
        if word == end:
            return dist
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nxt = word[:i] + c + word[i+1:]
                if nxt in unused:
                    unused.remove(nxt)
                    queue.append((nxt, dist + 1))
    return 0

