export function ladderLength(begin: string, end: string, words: string[]): number {
  const unused = new Set(words);
  const queue: Array<[string, number]> = [[begin, 1]];
  for (let qi = 0; qi < queue.length; qi += 1) {
    const [word, dist] = queue[qi];
    if (word === end) return dist;
    for (let i = 0; i < word.length; i += 1) {
      for (let code = 97; code <= 122; code += 1) {
        const next = word.slice(0, i) + String.fromCharCode(code) + word.slice(i + 1);
        if (unused.delete(next)) queue.push([next, dist + 1]);
      }
    }
  }
  return 0;
}

