def can_finish_dfs(count, prerequisites):
    graph = [[] for _ in range(count)]
    for course, need in prerequisites: graph[need].append(course)
    color = [0] * count
    def visit(course):
        if color[course] == 1: return False
        if color[course] == 2: return True
        color[course] = 1
