export function canFinishDfs(count: number, prerequisites: number[][]): boolean {
  const graph = Array.from({ length: count }, () => [] as number[]);
  for (const [course, need] of prerequisites) graph[need].push(course);
  const color = Array(count).fill(0);
  function visit(course: number): boolean {
    if (color[course] === 1) return false;
    if (color[course] === 2) return true;
    color[course] = 1;
    for (const next of graph[course]) if (!visit(next)) return false;
    color[course] = 2;
    return true;
  }
  return graph.every((_, course) => visit(course));
}

