def can_finish_bfs(count, prerequisites):
    graph = [[] for _ in range(count)]
    indegree = [0] * count
    for course, need in prerequisites:
        graph[need].append(course)
        indegree[course] += 1
    queue = deque(course for course in range(count) if indegree[course] == 0)
    completed = 0
    while queue:
        course = queue.popleft()
        completed += 1
        for next_course in graph[course]:
            indegree[next_course] -= 1
            if indegree[next_course] == 0: queue.append(next_course)
    return completed == count

