export function canFinishBfs(count: number, prerequisites: number[][]): boolean {
  const graph = Array.from({ length: count }, () => [] as number[]);
  const indegree = Array(count).fill(0);
  for (const [course, need] of prerequisites) { graph[need].push(course); indegree[course] += 1; }
  const queue = indegree.flatMap((degree, course) => degree === 0 ? [course] : []);
  let completed = 0;
  for (let head = 0; head < queue.length; head += 1) {
    const course = queue[head]; completed += 1;
    for (const next of graph[course]) if (--indegree[next] === 0) queue.push(next);
  }
  return completed === count;
}

