  for(int i=0;i<count;i++)graph[i]=new ArrayList<>();
  for(int[] edge:prerequisites){graph[edge[1]].add(edge[0]);indegree[edge[0]]++;}
  Queue<Integer> queue=new ArrayDeque<>();
  for(int i=0;i<count;i++)if(indegree[i]==0)queue.add(i);
  int completed=0;
  while(!queue.isEmpty()){int course=queue.remove();completed++;for(int next:graph[course])if(--indegree[next]==0)queue.add(next);}
  return completed==count;
}
